{"path": "_check.mjs", "content": "import assert from 'node:assert/strict';
import { mergeConfig } from './config.mjs';

// public tests
assert.deepEqual(mergeConfig({ mode: 'safe', retries: 3 }, { mode: 'fast' }),
  { mode: 'fast', retries: 3 });
assert.deepEqual(mergeConfig({ network: { host: 'localhost', port: 80 } }, { network: { port: 443 } }),
  { network: { host: 'localhost', port: 443 } });
assert.deepEqual(mergeConfig({ enabled: true, retries: 3 }, { enabled: false, retries: 0 }),
  { enabled: false, retries: 0 });

// TypeError cases
for (const bad of [null, undefined, [], 5, 'x', true]) {
  assert.throws(() => mergeConfig(bad), TypeError);
  assert.throws(() => mergeConfig({}, bad), TypeError);
}
assert.throws(() => mergeConfig(), TypeError);

// inherited keys ignored
const proto = { inherited: 1 };
const d = Object.create(proto); d.own = 2;
const o = Object.create(proto); o.own2 = 3;
assert.deepEqual(mergeConfig(d, o), { own: 2, own2: 3 });

// __proto__ and constructor as data keys from JSON.parse
const dj = JSON.parse('{"__proto__": {"a": 1}, "constructor": "c"}');
const oj = JSON.parse('{"__proto__": {"b": 2}}');
const r = mergeConfig(dj, oj);
assert.deepEqual(Object.keys(r).sort(), ['__proto__', 'constructor']);
assert.deepEqual(r['__proto__'], { a: 1, b: 2 });
assert.equal(r.constructor, 'c');
assert.equal(Object.getPrototypeOf(r), Object.prototype);

// null override replaces nested
assert.deepEqual(mergeConfig({ n: { a: 1 } }, { n: null }), { n: null });
// false/0/null replace
assert.deepEqual(mergeConfig({ a: 1, b: 2, c: 3 }, { a: false, b: 0, c: null }),
  { a: false, b: 0, c: null });

// no mutation / no retained references
const defaults = { net: { host: 'h', port: 1 }, top: 't' };
const overrides = { net: { port: 2 } };
const out = mergeConfig(defaults, overrides);
assert.deepEqual(defaults, { net: { host: 'h', port: 1 }, top: 't' });
assert.deepEqual(overrides, { net: { port: 2 } });
assert.notEqual(out.net, defaults.net);
assert.notEqual(out.net, overrides.net);
out.net.host = 'MUT';
assert.equal(defaults.net.host, 'h');

// independence across repeated calls
const a = mergeConfig(defaults, overrides);
const b = mergeConfig(defaults, overrides);
assert.notEqual(a, b);
assert.notEqual(a.net, b.net);
a.net.port = 999;
assert.equal(b.net.port, 2);

// nested override object not retained
const ov = { net: { port: 7 } };
const res = mergeConfig({ net: { host: 'x' } }, ov);
ov.net.port = 12345;
assert.equal(res.net.port, 7);

// nested default object not retained
const df = { net: { host: 'x' } };
const res2 = mergeConfig(df, { net: { port: 7 } });
df.net.host = 'CHANGED';
assert.equal(res2.net.host, 'x');

console.log('all checks passed');
"}

